import{_ as t,o as r,c as o,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Resellers Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Resellers Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/resellers-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Resellers Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/resellers-overview"}]]},"headers":[],"relativePath":"user-guide/resellers-overview.md","filePath":"user-guide/resellers-overview.md","lastUpdated":1787142963000}'),l={name:"user-guide/resellers-overview.md"};function a(i,e,d,n,c,m){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="resellers-module" tabindex="-1">Resellers Module <a class="header-anchor" href="#resellers-module" aria-label="Permalink to &quot;Resellers Module&quot;">​</a></h1><p>Phase 1 Sales module on the frozen platform. Workspace directory of <strong>reseller partners</strong> with two-tier commission rates (<code>commission_rate</code> for the reseller, <code>owner_commission_rate</code> for the workspace assignee / “owner” cut). Resellers link optionally onto customer invoices; commission ledger accrual lives in <strong>Reseller Payouts</strong>.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/resellers">resellers.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/resellers">resellers.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/resellers">resellers.md</a></td></tr><tr><td>Related module</td><td><a href="/user-guide/reseller-payouts-overview">Reseller Payouts</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-resellers">../api/tenant-v1-resellers.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Name, email, phone, company name, notes, status (active/inactive)</li><li>Two commission percentages: reseller rate and owner rate (0–100 each)</li><li>Assignment (<code>created_by</code> / <code>assigned_to</code>) with assignee scoping via <code>resellers.assign</code></li><li>Optional <strong>same-workspace</strong> login invite (<code>user_id</code>) — creates a user with only the protected <code>reseller</code> role</li><li>Soft delete with restore / force delete</li><li>Optional <code>reseller_id</code> on customer invoices (when Resellers is entitled)</li><li>Module licensing (<code>module:resellers</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong></li><li>Audit via <code>ResellerEventSubscriber</code> + Spatie <code>LogsActivity</code></li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>resellers.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>invite</code></p><p>Enable Resellers from Marketplace (free). Catalog: slug <code>resellers</code>, category <code>sales</code> (Sales), <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 70</code>. Hard dependency: <strong>Payments</strong>. Only Leads and Tasks install automatically on new workspaces.</p><h2 id="required-dependency" tabindex="-1">Required dependency <a class="header-anchor" href="#required-dependency" aria-label="Permalink to &quot;Required dependency&quot;">​</a></h2><p>Resellers <strong>requires Payments</strong> (<code>module_dependencies</code>, not optional). Marketplace blocks install until Payments is entitled — commission is driven by invoices that become fully <strong>Paid</strong> via the Payments ledger.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Cross-workspace identity (a reseller person spanning multiple tenants / Central identity)</li><li>Reseller portal / self-service outside the tenant SPA</li><li>Dashboard widgets for Resellers</li><li>Import/export</li><li>Automated payout disbursement (mark-paid is a ledger status, not a bank payout)</li></ul>',13)])])}const h=t(l,[["render",a]]);export{u as __pageData,h as default};
